    23→
    24→const getEventType = (event: EventTimelineItem) => {
    25→  if (
    26→    event.content.tag === TimelineItemContent_Tags.RtcNotification ||
    27→    event.content.tag === TimelineItemContent_Tags.CallInvite
    28→  ) {
    29→    return "call";
    30→  }
    31→  if (event.content.tag === TimelineItemContent_Tags.State) {
    32→    const stateContent = event.content.inner.content;
    33→    // This was used to handle call events in older versions of the SDK. Might be useful in the future.
    34→    // if (
    35→    //   stateContent.tag === OtherState_Tags.Custom &&
    36→    //   stateContent.inner?.eventType === "org.matrix.msc3401.call.member"
    37→    // ) {
    38→    //   return "call";
    39→    // }
    40→
    41→    if (stateContent.tag.includes("Room")) return "room";
    42→  }
    43→
    44→  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    45→    const kind = event.content.inner.content.kind;
    46→    if (kind?.tag === MsgLikeKind_Tags.Message) {
    47→      const msgType = kind.inner.content.msgType;
    48→
    49→      if (msgType?.tag === MessageType_Tags.Text) {
    50→        return "text";
    51→      } else if (msgType?.tag === MessageType_Tags.Image) {
    52→        return "image";
    53→      } else if (msgType?.tag === MessageType_Tags.File) {
    54→        return "file";
    55→      } else if (msgType?.tag === MessageType_Tags.Video) {
    56→        return "video";
    57→      } else if (msgType?.tag === MessageType_Tags.Audio) {
    58→        return "audio";
    59→      } else if (msgType?.tag === MessageType_Tags.Other) {
    60→        return "other";
    61→      } else {
    62→        return "unkown";
    63→      }
    64→    }
    65→
    66→    if (kind?.tag === MsgLikeKind_Tags.UnableToDecrypt) {
    67→      return "unableToDecrypt";
    68→    }
    69→  }
    70→  if (event.content.tag === TimelineItemContent_Tags.RoomMembership) {
    71→    return "membership";
    72→  }
    73→  if (event.content.tag === TimelineItemContent_Tags.ProfileChange) {
    74→    return "profile";
    75→  }
    76→  return "unkown";
    77→};
